import{_ as o,o as e,c as r,a5 as n}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"请求参数的绑定","description":"","frontmatter":{"title":"请求参数的绑定","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/请求参数的绑定.md","filePath":"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/请求参数的绑定.md"}'),p={name:"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/请求参数的绑定.md"};function c(a,t,u,l,i,g){return e(),r("div",null,[...t[0]||(t[0]=[n("<div><p>表单中请求参数都是基于 <code>key=value</code> 的。 <code>SpringMVC</code> 绑定请求参数的过程是通过把表单提交请求参数，作为控制器中方法参数进行绑定的。 例如：</p><p><code>\\&lt;a href=&quot;account/findAccount?accountId=10&quot;\\&gt;</code></p><p>查询账户</p><p><code>\\&lt;/a\\&gt;</code> 中请求参数是：</p><p>accountId=10 /** * 查询账户</p><ul><li>@return */ @RequestMapping(&quot;/findAccount&quot;) public String findAccount(Integer accountId) { System.out.println(&quot; 查询了账户。。。。</li></ul><p>&quot;+accountId); return &quot;success&quot;; } <strong>支持的数据类型：</strong><strong>基本类型参数：</strong> 包括基本类型和 <code>String</code> 类型 <code>POJO</code> <strong>类型参数：</strong> 包括实体类，以及关联的实体类 **数组和集合类型参数：**包括 <code>List</code> 结构和 <code>Map</code> 结构的集合（包括数组）</p><p><code>SpringMVC</code> 绑定请求参数是自动实现的，但是要想使用，必须遵循使用要求。</p><p><strong>使用要求：</strong><strong>如果是基本类型或者</strong> <code>String</code> <strong>类型：</strong> 要求我们的参数名称必须和控制器中方法的形参名称保持一致。<code>(</code>严格区分大小写<code>)</code></p><p><strong>如果是</strong> <code>POJO</code> <strong>类型，或者它的关联对象：</strong> 要求表单中参数名称和 <code>POJO</code> 类的属性名称保持一致。并且控制器方法的参数类型是 <code>POJO</code> 类型。</p><p><strong>如果是集合类型</strong><code>,</code><strong>有两种方式：</strong><strong>第一种：</strong> 要求集合类型的请求参数必须在 <code>POJO</code> 中。在表单中请求参数名称要和 <code>POJO</code> 中集合属性名称相同。 给 <code>List</code> 集合中的元素赋值，使用下标。 给 <code>Map</code> 集合中的元素赋值，使用键值对。 <strong>第二种：</strong> 接收的请求参数是 <code>json</code> 格式数据。需要借助一个注解实现。 <strong>注意</strong><code>:</code> 它还可以实现一些数据类型自动转换。内置转换器全都在： <code>org.springframework.core.convert.support</code> 包下。有：</p><p>java.lang.Boolean -&gt; java.lang.String : ObjectToStringConverter java.lang.Character -&gt; java.lang.Number : CharacterToNumberFactory java.lang.Character -&gt; java.lang.String : ObjectToStringConverter java.lang.Enum -&gt; java.lang.String : EnumToStringConverter java.lang.Number -&gt; java.lang.Character : NumberToCharacterConverter java.lang.Number -&gt; java.lang.Number : NumberToNumberConverterFactory java.lang.Number -&gt; java.lang.String : ObjectToStringConverter java.lang.String -&gt; java.lang.Boolean : StringToBooleanConverter java.lang.String -&gt; java.lang.Character : StringToCharacterConverter java.lang.String -&gt; java.lang.Enum : StringToEnumConverterFactory java.lang.String -&gt; java.lang.Number : StringToNumberConverterFactory java.lang.String -&gt; java.util.Locale : StringToLocaleConverter java.lang.String -&gt; java.util.Properties : StringToPropertiesConverter java.lang.String -&gt; java.util.UUID : StringToUUIDConverter java.util.Locale -&gt; java.lang.String : ObjectToStringConverter java.util.Properties -&gt; java.lang.String : PropertiesToStringConverter java.util.UUID -&gt; java.lang.String : ObjectToStringConverter ...... <strong>如遇特殊类型转换要求，需要我们自己编写自定义类型转换器。</strong></p><p><strong>使用示例</strong><code>3.1.4.1</code> <strong>基本类型和</strong> <code>String</code> <strong>类型作为参数</strong></p><p><code>jsp</code></p><p><strong>代码：</strong></p><p>&lt;a href=&quot;account/findAccount?accountId=10&amp;accountName=zhangsan&quot;&gt; 查询账户</p><p><code>\\&lt;/a\\&gt;</code><strong>控制器代码：</strong></p><p>@RequestMapping(&quot;/findAccount&quot;) public String findAccount(Integer accountId,String accountName) { System.out.println(&quot; 查询了账户。。。。</p><p>&quot;+accountId+&quot;,&quot;+accountName); return &quot;success&quot;; }</p><p><code>POJO</code> <strong>类型作为参数</strong><strong>实体类代码：</strong></p><p>public class Account implements Serializable { private Integer id; private String name; private Float money; private Address address; //getters and setters } ￼public class Address implements Serializable { private String provinceName; private String cityName; //getters and setters }</p><p><code>jsp</code> <strong>代码：</strong></p><p>&lt;form action=&quot;account/saveAccount&quot; method=&quot;post&quot;&gt; 账户名称：</p><p><code>\\&lt;input type=&quot;text&quot; name=&quot;name&quot; \\&gt;\\&lt;br/\\&gt;</code></p><p>￼账户金额：</p><p><code>\\&lt;input type=&quot;text&quot; name=&quot;money&quot; \\&gt;\\&lt;br/\\&gt;</code> 账户省份：</p><p>&lt;input type=&quot;text&quot; name=&quot;address.provinceName&quot; &gt;&lt;br/&gt; 账户城市：</p><p>&lt;input type=&quot;text&quot; name=&quot;address.cityName&quot; &gt;&lt;br/&gt; &lt;input type=&quot;submit&quot; value=&quot; <em>保存</em></p><ul><li>&quot;&gt;</li><li>&lt;/form&gt;</li></ul><p><strong>控制器代码：</strong></p><p>@RequestMapping(&quot;/saveAccount&quot;) public String saveAccount(Account account) { System.out.println(&quot; 保存了账户。。。。</p><p>&quot;+account); return &quot;success&quot;; }</p><p><code>POJO</code> <strong>类中包含集合类型参数</strong><strong>实体类代码：</strong></p><p>/** * 用户实体类</p><p>*/ public class User implements Serializable { private String username; private String password; private Integer age; private List&lt;Account&gt; accounts; private Map&lt;String,Account&gt; accountMap; //getters and setters @Override public String toString() { return &quot;User [username=&quot; + username + &quot;, password=&quot; + password + &quot;, age=&quot;</p><ul><li>age + &quot;,\\n accounts=&quot; + accounts</li><li>&quot;,\\n accountMap=&quot; + accountMap + &quot;]&quot;; } }</li></ul><p><code>jsp</code> <strong>代码：</strong></p><p><code>\\&lt;!-- POJO</code></p><p>类包含集合类型演示</p><p>--&gt; &lt;form action=&quot;account/updateAccount&quot; method=&quot;post&quot;&gt; 用户名称：</p><p><code>\\&lt;input type=&quot;text&quot; name=&quot;username&quot; \\&gt;\\&lt;br/\\&gt;</code> 用户密码：</p><p><code>\\&lt;input type=&quot;password&quot; name=&quot;password&quot; \\&gt;\\&lt;br/\\&gt;</code> 用户年龄：</p><p><code>\\&lt;input type=&quot;text&quot; name=&quot;age&quot; \\&gt;\\&lt;br/\\&gt;</code> 账户</p><p><code>1</code></p><p>名称：</p><p>&lt;input type=&quot;text&quot; name=&quot;accounts[0].name&quot; &gt;&lt;br/&gt; 账户</p><p><code>1</code></p><p>金额：</p><p>&lt;input type=&quot;text&quot; name=&quot;accounts[0].money&quot; &gt;&lt;br/&gt; 账户</p><p><code>2</code></p><p>名称：</p><p>&lt;input type=&quot;text&quot; name=&quot;accounts[1].name&quot; &gt;&lt;br/&gt; 账户</p><p><code>2</code></p><p>金额：</p><p>&lt;input type=&quot;text&quot; name=&quot;accounts[1].money&quot; &gt;&lt;br/&gt; 账户</p><p><code>3</code></p><p>名称：</p><p>&lt;input type=&quot;text&quot; name=&quot;accountMap[&#39;one&#39;].name&quot; &gt;&lt;br/&gt; 账户</p><p><code>3</code></p><p>金额：</p><p>&lt;input type=&quot;text&quot; name=&quot;accountMap[&#39;one&#39;].money&quot; &gt;&lt;br/&gt; 账户</p><p><code>4</code></p><p>名称：</p><p>&lt;input type=&quot;text&quot; name=&quot;accountMap[&#39;two&#39;].name&quot; &gt;&lt;br/&gt; 账户</p><p><code>4</code></p><p>金额：</p><p>&lt;input type=&quot;text&quot; name=&quot;accountMap[&#39;two&#39;].money&quot; &gt;&lt;br/&gt; &lt;input type=&quot;submit&quot; value=&quot; <em>保存</em></p><ul><li>&quot;&gt;</li><li>&lt;/form&gt;</li></ul><p><strong>控制器代码：</strong></p><p>/** * 更新账户</p><p>*/ @RequestMapping(&quot;/updateAccount&quot;) public String updateAccount(User user) { System.out.println(&quot; 更新了账户。。。。</p><p>&quot;+user); return &quot;success&quot;; } **￼**<strong>请求参数乱码问题</strong><code>post</code> <strong>请求方式：</strong> 在</p><p><code>web.xml</code></p><p>中配置一个过滤器</p><p><code>\\&lt;!--</code></p><p>配置 <code>springMVC</code> 编码过滤器</p><p>--&gt; &lt;filter&gt; &lt;filter-name&gt;CharacterEncodingFilter&lt;/filter-name&gt; &lt;filter-class&gt; org.springframework.web.filter.CharacterEncodingFilter &lt;/filter-class&gt; &lt;!-- 设置过滤器中的属性值</p><ul><li>--&gt;</li><li>&lt;init-param&gt;</li><li>&lt;param-name&gt;encoding&lt;/param-name&gt;</li><li>&lt;param-value&gt;UTF-8&lt;/param-value&gt;</li><li>&lt;/init-param&gt;</li><li>&lt;!--</li></ul><p>启动过滤器</p><ul><li>--&gt;</li><li>&lt;init-param&gt;</li><li>&lt;param-name&gt;forceEncoding&lt;/param-name&gt;</li><li>&lt;param-value&gt;true&lt;/param-value&gt;</li><li>&lt;/init-param&gt;</li><li>&lt;/filter&gt;</li><li>&lt;!--</li></ul><p>过滤所有请求</p><p>--&gt; &lt;filter-mapping&gt; &lt;filter-name&gt;CharacterEncodingFilter&lt;/filter-name&gt; &lt;url-pattern&gt;/*&lt;/url-pattern&gt; &lt;/filter-mapping&gt; 在</p><p><code>springmvc</code></p><p>的配置文件中可以配置，静态资源不过滤：</p><p><code>\\&lt;!-- location</code></p><p>表示路径，<code>mapping</code> 表示文件，<code>**</code>表示该目录下的文件以及子目录的文件</p><p>--&gt; &lt;mvc:resources location=&quot;/css/&quot; mapping=&quot;/css/<strong>&quot;/&gt; &lt;mvc:resources location=&quot;/images/&quot; mapping=&quot;/images/</strong>&quot;/&gt; &lt;mvc:resources location=&quot;/scripts/&quot; mapping=&quot;/javascript/**&quot;/&gt;</p><p><code>get</code> <strong>请求方式：</strong></p><p><code>tomacat</code></p><p>对 <code>GET</code> 和 <code>POST</code> 请求处理方式是不同的，<code>GET</code> 请求的编码问题，要改 <code>tomcat</code> 的 <code>server.xml</code> 配置文件，如下：</p><ul><li>&lt;Connector connectionTimeout=&quot;20000&quot; port=&quot;8080&quot;</li><li>protocol=&quot;HTTP/1.1&quot; redirectPort=&quot;8443&quot;/&gt;</li></ul><p>改为：</p><ul><li>&lt;Connector connectionTimeout=&quot;20000&quot; port=&quot;8080&quot;</li><li>protocol=&quot;HTTP/1.1&quot; redirectPort=&quot;8443&quot;</li><li>useBodyEncodingForURI=&quot;true&quot;/&gt;</li></ul><p>如果遇到</p><p><code>ajax</code></p><p>请求仍然乱码，请把：</p><p><code>useBodyEncodingForURI=&quot;true&quot;</code></p><p>改为</p><p><code>URIEncoding=&quot;UTF-8&quot;</code> 即可。</p><p><strong>特殊情况</strong><strong>自定义类型转换器</strong> 使用场景</p><ul><li>:</li><li>jsp</li></ul><p><strong>代码：</strong><code>\\&lt;!--</code> <strong>特殊情况之：类型转换问题</strong></p><ul><li>--&gt;</li><li>&lt;a href=&quot;account/deleteAccount?date=2018-01-01&quot;&gt;</li></ul><p>根据日期删除账户</p><p><code>\\&lt;/a\\&gt;</code><strong>控制器代码：</strong></p><p>/** * 删除账户</p><p>*/ @RequestMapping(&quot;/deleteAccount&quot;) public String deleteAccount(String date) { System.out.println(&quot; 删除了账户。。。。</p><p>&quot;+date); return &quot;success&quot;; } <strong>运行结果：</strong><strong>当我们把控制器中方法参数的类型改为</strong></p><p><code>Date</code></p><p><strong>时：</strong></p><p>/** * 删除账户</p><ul><li>@return */ @RequestMapping(&quot;/deleteAccount&quot;) public String deleteAccount(Date date) { System.out.println(&quot; 删除了账户。。。。</li></ul><p>&quot;+date); return &quot;success&quot;; } <strong>运行结果：</strong></p><p><strong>异常提示：</strong></p><p>Failed to bind request element: org.springframework.web.method.annotation.MethodArgumentTypeMismatchExcept ion: Failed to convert value of type &#39;java.lang.String&#39; to required type ￼</p><p>&#39;java.util.Date&#39;; nested exception is org.springframework.core.convert.ConversionFailedException: Failed to convert from type [java.lang.String] to type [java.util.Date] for value &#39;2018-01-01&#39;; nested exception is java.lang.IllegalArgumentException 使用步骤 <strong>第一步：定义一个类，实现</strong></p><p><code>Converter</code></p><p><strong>接口，该接口有两个泛型。</strong></p><p>public interface Converter&lt;S, T&gt; {//S: 表示接受的类型，<code>T</code>：表示目标类型</p><p>/** * 实现类型转换的方法</p><p>*/ @Nullable T convert(S source); }</p><p>/** * 自定义类型转换器</p><p><em>/ public class StringToDateConverter implements Converter&lt;String, Date&gt; { /</em>* * 用于把 <code>String</code> 类型转成日期类型</p><p>*/ @Override public Date convert(String source) { DateFormat format = null; try { if(StringUtils.isEmpty(source)) { throw new NullPointerException(&quot; 请输入要转换的日期</p><p>&quot;); } format = new SimpleDateFormat(&quot;yyyy-MM-dd&quot;); Date date = format.parse(source); return date; } catch (Exception e) { throw new RuntimeException(&quot; 输入日期有误</p><p>&quot;); } } } <strong>第二步：在</strong></p><p><code>spring</code></p><p><strong>配置文件中配置类型转换器。</strong></p><p><code>spring</code></p><p>配置类型转换器的机制是，将自定义的转换器注册到类型转换服务中去。￼<code>\\&lt;!--</code> 配置类型转换器工厂</p><p>--&gt; &lt;bean id=&quot;converterService&quot; class=&quot;org.springframework.context.support.ConversionServiceFactoryBean&quot;&gt; &lt;!-- 给工厂注入一个新的类型转换器</p><ul><li>--&gt;</li><li>&lt;property name=&quot;converters&quot;&gt;</li><li>&lt;array&gt;</li><li>&lt;!--</li></ul><p>配置自定义类型转换器</p><p>--&gt; &lt;bean class=&quot;com.itheima.web.converter.StringToDateConverter&quot;&gt;&lt;/bean&gt; &lt;/array&gt; &lt;/property&gt; &lt;/bean&gt; <strong>第三步：在</strong></p><p><code>annotation-driven</code></p><p><strong>标签中引用配置的类型转换服务</strong></p><p><code>\\&lt;!--</code></p><p>引用自定义类型转换器</p><p>--&gt; &lt;mvc:annotation-driven conversion-service=&quot;converterService&quot;&gt;&lt;/mvc:annotation-driven&gt; <strong>使用</strong> <code>ServletAPI</code> <strong>对象作为方法参数</strong><code>SpringMVC</code> 还支持使用原始 <code>ServletAPI</code> 对象作为控制器方法的参数。支持原始 <code>ServletAPI</code> 对象有：</p><ul><li><code>HttpServletRequest</code></li><li><code>HttpServletResponse</code></li><li><code>HttpSession</code></li><li><code>java.security.Principal</code></li><li><code>Locale</code></li><li><code>InputStream</code></li><li><code>OutputStream</code></li><li><code>Reader</code></li><li><code>Writer</code></li></ul><p><strong>我们可以把上述对象，直接写在控制的方法参数中使用。</strong><strong>部分示例代码：</strong></p><p><code>jsp</code></p><p><strong>代码：</strong></p><p><code>\\&lt;!--</code></p><p>原始 <code>ServletAPI</code> 作为控制器参数</p><ul><li>--&gt;</li><li>&lt;a href=&quot;account/testServletAPI&quot;&gt;</li></ul><p>测试访问</p><p><code>ServletAPI\\&lt;/a\\&gt;</code><strong>控制器中的代码：</strong></p><p>/** * 测试访问 <code>testServletAPI</code>传智播客——专注于 <code>Java</code>、<code>.Net</code> 和<code>Php</code>、网页平面设计工程师的培训</p><ul><li>@return */ @RequestMapping(&quot;/testServletAPI&quot;) public String testServletAPI(HttpServletRequest request, HttpServletResponse response, HttpSession session) { System.out.println(request); System.out.println(response); System.out.println(session); return &quot;success&quot;; } <strong>执行结果：</strong></li></ul></div>",1)])])}const q=o(p,[["render",c]]);export{d as __pageData,q as default};
